void qtd_disconnect(void* c) { auto* p = static_cast<QMetaObject::Connection*>(c);
    QObject::disconnect(*p); delete p; }
// ...and DROPPING the handle without severing the connection, which is the common case:
// a caller that ignores the returned QtdConnection still wants the signal wired. Only the
// QMetaObject::Connection this allocated is freed; the connection itself belongs to the
// sender and dies with it (releasing the delegate box through DHolder).
void qtd_conn_free(void* c) { delete static_cast<QMetaObject::Connection*>(c); }
